"""Writes runtime/src/game_signatures_206.inc from signatures206.json (generated by gen206.py)."""
import json
from pathlib import Path
here = Path(__file__).parent
data = json.loads((here / 'signatures206.json').read_text())
EXPECT = {'closeEvent': 'Expect::Writable', 'cursorClass': 'Expect::ReadOnly'}
METHOD = {'code': 'Method::Code', 'reference': 'Method::Reference', 'rtti': 'Method::Rtti', 'slot': 'Method::Slot'}
rows = []
for f in data['fields']:
    n = f['name']
    pattern = f'"{f["pattern"]}"' if 'pattern' in f else 'nullptr'
    cls = f'"{f["cls"]}"' if 'cls' in f else 'nullptr'
    calls = f'"{f["calls"]}"' if f.get('calls') else 'nullptr'
    rows.append(f'    {{"{n}",{METHOD[f["method"]]},{EXPECT.get(n, "Expect::Code")},false,{pattern},'
                f'{f.get("offset", 0)},{f.get("disp", 0)},{f.get("end", 0)},{cls},0x{f["rva"]:x},0x{f.get("slot", 0):x},{calls}}},')
exe = data['exe']
text = ('// Generated by runtime/tools/signatures/emit206.py from signatures206.json. Do not edit.\n'
        f'// Source build: Steam 2.06, stamp 0x{exe["stamp"]:x}, image size 0x{exe["size"]:x}, checksum 0x{exe["checksum"]:x}.\n'
        '// Each row: field, method, where it must lie, must be a call, pattern, code offset, disp32 offset,\n'
        '// instruction end, RTTI class, address in the source build, vtable slot, function the site must call.\n'
        + '\n'.join(rows) + '\n')
out = here.parents[1] / 'src' / 'game_signatures_206.inc'
out.write_text(text, encoding='utf-8')
print(out, len(rows), 'rows')
